import java.util.*; abstract class Student09{String name;Student09(String n){name=n;}abstract double fee();} class Day09 extends Student09{Day09(String n){super(n);}double fee(){return 52000;}} class Hosteller09 extends Student09{Hosteller09(String n){super(n);}double fee(){return 100000;}} class Scholar09 extends Student09{Scholar09(String n){super(n);}double fee(){return 32000;}} public class Week09Problem03{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();for(int i=0;i<n;i++){String t=s.next().toUpperCase(),name=s.next();Student09 a=t.equals("HOSTELLER")?new Hosteller09(name):t.equals("SCHOLAR")?new Scholar09(name):new Day09(name);System.out.printf("%s: %.2f%n",a.name,a.fee());}}}